        else element.setAttribute('aria-modal', entry.modal)
        if (entry.tabIndex === null) element.removeAttribute('tabindex')
        else element.setAttribute('tabindex', entry.tabIndex)
      }
      entries.clear()
      listeners.clear()
      current = undefined
    },
  }
