    super(reason + ' invalidated')
  }
}
const messageOf = (error: unknown): string =>
  error instanceof Error ? error.message : String(error)
function bounded<T>(
  promise: Promise<T>,
  milliseconds: number,
  phase: string,
  late?: (value: T) => void,
): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    let finished = false
    const timer = setTimeout(() => {
      finished = true
      reject(new Error(phase + ' deadline exceeded (' + milliseconds + 'ms)'))
    }, milliseconds)
    promise.then(
      (value) => {
        if (finished) {
          late?.(value)
          return
        }
        finished = true
        clearTimeout(timer)
        resolve(value)
      },
      (error) => {
        if (finished) return
        finished = true
        clearTimeout(timer)
        reject(error)
      },
    )
  })
}
